## Why This Is Asked
This question tests your ability to model cross-language callbacks, manage memory ownership, and handle streaming data in CGO. You must coordinate Go and C lifetimes, ensure safe callbacks from C into Go, and design backpressure-aware consumption.

## Key Concepts
- **CGO callbacks**: Exporting Go functions for C to call safely using cgo export
- **Memory ownership**: C allocates chunks via `malloc`, Go frees them to prevent leaks
- **Streaming via channels**: Using Go channels to receive pushed data from C
- **Backpressure**: Ensuring the consumer can signal when it cannot keep up
- **Thread safety**: Managing concurrent access to shared state between C threads and Go runtime

## Code Example
```c
// cgowa_stream.h
typedef void (*chunk_cb)(const char* data, size_t len, void* user);

void* start_stream(const char* source_id, chunk_cb on_chunk, void* user);
void stop_stream(void* handle);
```

```c
// cgowa_stream.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "cgowa_stream.h"

struct stream_context {
    chunk_cb callback;
    void* user;
    pthread_t thread;
    int running;
};

static void* stream_thread(void* arg) {
    struct stream_context* ctx = arg;
    const char* chunks[] = {"{\"id\":1}", "{\"id\":2}", "{\"id\":3}"};

    for (int i = 0; i < 3 && ctx->running; i++) {
        size_t len = strlen(chunks[i]);
        ctx->callback(chunks[i], len, ctx->user);
        sleep(1);
    }
    return NULL;
}

void* start_stream(const char* source_id, chunk_cb on_chunk, void* user) {
    struct stream_context* ctx = malloc(sizeof(struct stream_context));
    ctx->callback = on_chunk;
    ctx->user = user;
    ctx->running = 1;
    pthread_create(&ctx->thread, NULL, stream_thread, ctx);
    return ctx;
}

void stop_stream(void* handle) {
    struct stream_context* ctx = handle;
    ctx->running = 0;
    pthread_join(ctx->thread, NULL);
    free(ctx);
}
```

```go
// stream.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lstream
#include "cgowa_stream.h"
#include <stdlib.h>

extern void chunkProxy(const char* data, size_t len, void* user);

static void* go_start_stream(const char* source_id, void* user) {
    return start_stream(source_id, chunkProxy, user);
}
*/
import "C"

import (
    "encoding/json"
    "fmt"
    "runtime"
    "sync"
    "unsafe"
)

type StreamHandler struct {
    ch     chan string
    done   chan struct{}
    mu     sync.Mutex
    handle C void
}

var handlers = make(map[*StreamHandler]struct{}{})
var handlersMu sync.RWMutex

//export chunkProxy
func chunkProxy(data *C.char, len C.size_t, user unsafe.Pointer) {
    handlersMu.RLock()
    defer handlersMu.RUnlock()

    handler := (*StreamHandler)(user)
    if handler == nil {
        return
    }

    chunk := C.GoStringN(data, C.int(len))

    select {
    case handler.ch <- chunk:
    default:
    }
}

func StartStream(source string) (chan string, error) {
    ch := make(chan string, 10)
    handler := &StreamHandler{
        ch:   ch,
        done: make(chan struct{}),
    }

    handlersMu.Lock()
    handlers[handler] = struct{}{}
    handlersMu.Unlock()

    cSource := C.CString(source)
    defer C.free(unsafe.Pointer(cSource))

    handle := C.go_start_stream(cSource, unsafe.Pointer(handler))
    handler.handle = handle

    return ch, nil
}

func StopStream(handler *StreamHandler) {
    handler.mu.Lock()
    defer handler.mu.Unlock()

    if handler.handle != nil {
        C.stop_stream(handler.handle)
        handler.handle = nil
    }

    close(handler.ch)

    handlersMu.Lock()
    delete(handlers, handler)
    handlersMu.Unlock()
}

func main() {
    ch, err := StartStream("source-123")
    if err != nil {
        panic(err)
    }

    var wg sync.WaitGroup
    wg.Add(1)

    go func() {
        defer wg.Done()
        dec := json.NewDecoder(ch)

        for {
            select {
            case <-ch:
                var data map[string]interface{}
                if err := dec.Decode(&data); err != nil {
                    fmt.Printf("Parse error: %v\n", err)
                    continue
                }
                fmt.Printf("Received: %v\n", data)
                runtime.Gosched()
            }
        }
    }()

    wg.Wait()
}
```

## Why This Is Asked
Tests ability to bridge Go and C with callbacks, manage lifetimes, and avoid unsafe pointer passes.

## Key Concepts
- CGO callbacks and trampolines
- cgo.Handle for Go values across C boundaries
- Memory ownership and handle release
- Thread-safety when called from C across Go threads

## Complete Implementation

**C Header (stream.h):**
```c
typedef void (*cb_t)(int, void*);
void register_stream(cb_t cb, void* user);
void trampoline(int value, void* handle_ptr);
void unregister_stream(void);
```

**C Trampoline (stream.c):**
```c
#include "stream.h"
#include <stdint.h>

void trampoline(int value, void* handle_ptr) {
    uintptr_t handle = (uintptr_t)handle_ptr;
    // This calls back into Go via cgo.Handle
    extern void go_callback(int value, uintptr_t handle);
    go_callback(value, handle);
}
```

**Go Binding:**
```go
/*
#cgo LDFLAGS: -L. -lstream
#include "stream.h"
*/
import "C"
import "unsafe"

var activeStreams = make(map[uintptr]chan int)
var streamsMutex sync.RWMutex

//export go_callback
func go_callback(value C.int, handlePtr C.uintptr_t) {
    handle := uintptr(handlePtr)
    streamsMutex.RLock()
    if ch, exists := activeStreams[handle]; exists {
        select {
        case ch <- int(value):
        default:
            // Channel full, drop value
        }
    }
    streamsMutex.RUnlock()
}

func StartStream() (<-chan int, func()) {
    ch := make(chan int, 100)

    // Create wrapper function and handle
    done := make(chan struct{})
    handle := C.uintptr_t(C.NewHandle(done))

    streamsMutex.Lock()
    activeStreams[uintptr(handle)] = ch
    streamsMutex.Unlock()

    // Register with C trampoline
    C.register_stream((*[0]byte)(C.trampoline), unsafe.Pointer(handle))

    // Cleanup function
    cleanup := func() {
        C.unregister_stream()
        C.Delete(C.Handle(handle))

        streamsMutex.Lock()
        delete(activeStreams, uintptr(handle))
        streamsMutex.Unlock()

        close(ch)
    }

    return ch, cleanup
}

// Usage example:
func consumeStreams() {
    stream1, stop1 := StartStream()
    stream2, stop2 := StartStream()

    go func() {
        for val := range stream1 {
            fmt.Printf("Stream 1: %d\n", val)
        }
    }()

    go func() {
        for val := range stream2 {
            fmt.Printf("Stream 2: %d\n", val)
        }
    }()

    // Stop after some time
    time.Sleep(5 * time.Second)
    stop1()
    stop2()
}
```

